export function hoverScreen4() {
 const levels = document.querySelectorAll('.screen4__point');
 const descriptions = document.querySelectorAll('.screen4__style');

 const mediaQuery = window.matchMedia('(min-width: 1025px)');

  if (!levels.length) return;

  levels.forEach((level) => {
    const dataTitle = level.getAttribute('data-level');
    const description = document.querySelector(`[data-info-list='${dataTitle}']`)
    const title = level.querySelector('.screen4__point-name');
    const btnInfo = level.querySelector('.screen4__btn-info');

    if (!description) return;

    function handleMouseOver ()  {
      description.classList.add('active');
    }

    function handleMouseOut ()  {
      description.classList.remove('active');
    }

    function handleBtnClick (e) {
      e.stopPropagation();
      descriptions.forEach((elem) => {
        if (elem !== description){
          elem.classList.remove('active');
        }
      })
      description.classList.toggle('active');
    }

    description.addEventListener('click', (e) => {
      e.stopPropagation();
    })

    function setupEventListener (e) {
      if (e.matches) {
        btnInfo.removeEventListener('click', handleBtnClick);
        title.addEventListener('mouseover', handleMouseOver);
        title.addEventListener('mouseout', handleMouseOut);
      }else {
        description.classList.remove('active');
        title.removeEventListener('mouseover', handleMouseOver);
        title.removeEventListener('mouseout', handleMouseOut);
        btnInfo.addEventListener('click', handleBtnClick);
      }
    }

    setupEventListener(mediaQuery);
    mediaQuery.addEventListener('change', setupEventListener);
  })
  document.addEventListener('click', () => {
    descriptions.forEach((elem) => {
      elem.classList.remove('active');
    })
  })
}