export function circleProgress () {
  const container = document.querySelector('.screen5__circle-container')
  const svgElement = document.querySelector('.screen5__circle-svg');
  const circlePath = document.getElementById('circle-screen5');
  const circleTrack = document.querySelector('.screen5__slider-track');
  const bigDot  = document.querySelector('.screen5__big-dot')
  const buttons = document.querySelectorAll('.screen5__circle-dot')

  if (!container || !circlePath || !circleTrack || !buttons.length) return;

  const strokeWidth = 2;
  let currentAngle = -Math.PI/2;
  let angles = [];
  let svgCentre;
  let svgRadius;
  let circumference;
  let animationFrame = null;

  function easeInOutCubic(t) {
    return t < 0.5
      ? 4 * t * t * t
      : 1 - Math.pow(-2 * t + 2, 3) / 2;
  }

  function initCircle () {
    const wrapperSize = container.offsetWidth;
    if (wrapperSize === 0) return;

    svgCentre = wrapperSize / 2;
    svgRadius = svgCentre - (strokeWidth / 2);
    circumference = 2 * Math.PI * svgRadius;

    svgElement.setAttribute('viewBox', `0 0 ${wrapperSize} ${wrapperSize}`)
    circleTrack.setAttribute('cx', svgCentre);
    circleTrack.setAttribute('cy', svgCentre);
    circleTrack.setAttribute('r', svgRadius);
    circlePath.setAttribute('cx', svgCentre);
    circlePath.setAttribute('cy', svgCentre);
    circlePath.setAttribute('r', svgRadius);
    circlePath.style.strokeDasharray  = `${circumference}`;

    circlePath.style.strokeDasharray = `${circumference}`;
    circlePath.style.strokeDashoffset = `${circumference}`;

    angles = [...buttons].map((_, i) =>
      (i / buttons.length) * 2 * Math.PI - Math.PI / 2);

    buttons.forEach((btn, i) =>{
      const x = svgCentre + svgRadius * Math.cos(angles[i]);
      const y = svgCentre + svgRadius * Math.sin(angles[i]);
      btn.style.left = `${x}px`;
      btn.style.top = `${y}px`;
    })

    const startX = svgCentre + svgRadius * Math.cos(currentAngle);
    const startY = svgCentre + svgRadius * Math.sin(currentAngle);
    bigDot.style.left = `${startX}px`;
    bigDot.style.top = `${startY}px`;
  }

  function moveBigDotTo (index) {
    const targetAngle = angles[index];
    let deltaAngle = targetAngle - currentAngle;
    deltaAngle = ((deltaAngle + Math.PI) % (2 * Math.PI)) - Math.PI;
    const duration = 100;
    const startTime = performance.now();
    const startAngle = currentAngle;

    if (animationFrame) cancelAnimationFrame(animationFrame);

    function animate(time) {
      const elapsed = time - startTime;
      const progress = Math.min(elapsed / duration, 1);
      const easedProgress = easeInOutCubic(progress);
      const angle = startAngle + deltaAngle * easedProgress;

      const x = svgCentre + svgRadius * Math.cos(angle);
      const y = svgCentre + svgRadius * Math.sin(angle);
      bigDot.style.left = `${x}px`;
      bigDot.style.top = `${y}px`;

      const progressCircle = ((angle + Math.PI / 2) / (2 * Math.PI)) * circumference;
      circlePath.style.strokeDashoffset = `${circumference - progressCircle}`;

      currentAngle = angle;

      if (progress < 1) requestAnimationFrame(animate);
      else currentAngle = targetAngle
    }

    requestAnimationFrame(animate);
  }

  function setup() {
    initCircle();
    let activeIndex = 0;

    buttons.forEach((btn, i) =>{
      btn.classList.remove('active', 'completed');
      if (i < activeIndex) btn.classList.add('completed');
    });
    buttons[activeIndex].classList.add('active');
    moveBigDotTo(activeIndex);


    buttons.forEach((btn, i) =>{
      btn.addEventListener('click', () => {
        activeIndex = i;
        buttons.forEach((btn, idx) =>{
          btn.classList.remove('active', 'completed');
          if (idx < activeIndex) btn.classList.add('completed');
        });
        buttons[activeIndex].classList.add('active');
        moveBigDotTo(activeIndex);
      })
    })
  }

  setup()

  window.addEventListener('resize', setup)
}